contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public property test function
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this contract has enough balance to send `amount`
        require(address(this).balance >= amount);

        // observe before-values
        address beforeBank = c.bank(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        bool reverted;
        // make the deciding call
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-values
        address afterBank = c.bank(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // General rule:
        // If caller sends exactly the ticket amount then the bank address does not change,
        // and the contract's external balance cannot increase by more than that ticket amount as a result.
        // (This rules out unexpected balance inflation in a single play call.)
        assert((amount == 10 && !reverted && afterBank == beforeBank && afterBalance <= beforeBalance + amount)
               || (amount == 10 && reverted && afterBank == beforeBank && afterBalance == beforeBalance)
               || (amount != 10));
    }

    receive() external payable { }
}

