// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        address beforeBank;
        try c.bank() returns (address __r) { beforeBank = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        address afterBank;
        try c.bank() returns (address __r) { afterBank = __r; } catch { return; }
        uint afterBalance = address(c).balance;
        assertTrue((amount == 10 && !reverted && afterBank == beforeBank && afterBalance <= beforeBalance + amount)
               || (amount == 10 && reverted && afterBank == beforeBank && afterBalance == beforeBalance)
               || (amount != 10));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable { }
}
